82		/**
83		 * A first request for every key, unless a test says otherwise: the port resolves what it
84		 * was handed, runs the operation over the result and returns what that answered. Without
85		 * it every assertion in this class about the {@code 201} would be made against the {@code
86		 * null} an unstubbed mock returns, which is not what an endpoint with no duplicate to
87		 * resolve does.
88		 *
89		 * <p>Both phases are run here rather than only the operation, because the order they run
90		 * in is the port's contract and this stub stands in for it. A stub that skipped the
91		 * resolution would let the endpoint pass while handing phase three something it never
92		 * quoted.
93		 *
94		 * <p>The tests that replace this stubbing use {@code willX().given(mock)} rather
95		 * than {@code given(mock.x())}, because the second form <em>calls</em> the mock to
96		 * record what to stub — and calling it here runs the answer above against the null
97		 * arguments the matchers stand in for.
98		 */
99		@BeforeEach
100		void runWhateverTheEndpointHandsToTheIdempotentPort() {
101			given(requests.executeOnce(any(), any(), any(), any(), any()))
102					.willAnswer(call -> call.getArgument(4, Function.class)
103							.apply(call.getArgument(3, Supplier.class).get()));
104		}
105	
106		@Test
107		@DisplayName("requesting a Transfer answers 201 with the PENDING Transfer it created")
108		void answersCreatedWithThePendingTransferItRequested() {
109			ReservationRequest expected = new ReservationRequest(5L, 9L, 100_50L, REQUESTED_AT);
110			stubBothPhases(31L, expected, sameCurrency(expected, Currency.EUR));
111	
112			MvcTestResult result = request("""
113					{"fromAccountId": 5, "toAccountId": 9, "amountMinorUnits": 10050}""");
114	
115			assertThat(result).hasStatus(HttpStatus.CREATED);
116			assertThat(result).hasContentTypeCompatibleWith(MediaType.APPLICATION_JSON);
117			assertThat(result).bodyJson().extractingPath("$.id").isEqualTo(31);
118			assertThat(result).bodyJson().extractingPath("$.fromAccountId").isEqualTo(5);
