217		/**
218		 * The key is required from this endpoint's first version, and does nothing yet: the
219		 * guarantee behind it is ticket 17's. Requiring it now is what stops a client ever
220		 * being written against a version that let them opt out, which is the version that
221		 * would still be in production when the guarantee arrives.
222		 */
223		@Nested
224		@DisplayName("the Idempotency Key")
225		class IdempotencyKey {
226	
227			@Test
228			@DisplayName("is required, and a request without one never reaches the reservation")
229			void isRequired() {
230				MvcTestResult result = requestWithNoKey(VALID_PAYLOAD).exchange();
231	
232				assertThatNamesARejectedField(result, "idempotencyKey");
233				then(reservation).shouldHaveNoInteractions();
