235	
236			/**
237			 * A key that is not a UUID is refused rather than accepted as an opaque string.
238			 * Keys are globally scoped, so the only thing standing between a caller and
239			 * squatting on someone else's key is that guessing one is a 122-bit problem —
240			 * which is a property of UUIDs and not of arbitrary text.
241			 */
242			@Test
243			@DisplayName("has to be a well-formed UUID")
244			void hasToBeAWellFormedUuid() {
245				MvcTestResult result = requestWithKey("not-a-uuid", VALID_PAYLOAD);
246	
247				assertThatNamesARejectedField(result, "idempotencyKey");
248				then(reservation).shouldHaveNoInteractions();
249			}
250	
251			/**
252			 * Well-formed is the whole of the rule: any version, either letter case. Both of
253			 * these are keys a client library hands out today — {@code uuidv7} is the default
254			 * in several, and a key that has been through an uppercasing log or an HTTP client
255			 * that normalises headers is still the same 122 bits.
256			 *
257			 * <p>Hibernate Validator's {@code @UUID} defaults to {@code version = {1, 2, 3, 4,
258			 * 5}} and {@code letterCase = LOWER_CASE}, so both of these are {@code 400} under
259			 * the bare annotation — an annotation named for the format accepting less than the
260			 * format.
261			 */
