263			@ValueSource(strings = {
264					"0D1F6C1E-6B0A-4A5F-9F1A-2C3D4E5F6A7B",
265					"019249a4-8f3c-7c2e-b1d5-9e6f0a1b2c3d"})
266			@DisplayName("is any well-formed UUID, whatever its version or letter case")
267			void acceptsAnyWellFormedUuid(String idempotencyKey) {
268				ReservationRequest expected = new ReservationRequest(5L, 9L, 100_50L, REQUESTED_AT);
269				given(reservation.reserve(expected)).willReturn(pendingTransfer(31L, expected, Currency.EUR));
270	
271				MvcTestResult result = requestWithKey(idempotencyKey, VALID_PAYLOAD);
272	
273				assertThat(result).hasStatus(HttpStatus.CREATED);
274			}
275	
276			/**
277			 * The one well-formed key that is refused, and for the reason above rather than
278			 * despite it: the all-zero UUID is the value every client that forgot to generate
279			 * one arrives with, so it is the one key two callers would collide on.
280			 */
