287				then(reservation).shouldHaveNoInteractions();
288			}
289		}
290	
291		/**
292		 * The endpoint's half of design decision 5: it hands the key, what the request said and
293		 * the operation to the port, and answers whatever comes back — including the two
294		 * refusals, which are the only ones here that are not {@code 422}.
295		 *
296		 * <p>The two {@code 409}s share a status and mean opposite things, so both halves of
297		 * what tells them apart are asserted every time: the {@code type} URN a client branches
298		 * on, and the {@code Retry-After} that says whether coming back can ever help.
299		 */
300		@Nested
301		@DisplayName("a repeat of an Idempotency Key")
302		class Repeats {
303	
304			/**
305			 * The guarantee as a client sees it. The response is the first request's, so the
306			 * {@code Location} still points at the Transfer that already exists — and the
307			 * reservation is never reached, which is the half that says no second Transfer was
308			 * created rather than merely that none was reported.
309			 */
310			@Test
311			@DisplayName("replays the first request's 201 without reserving anything again")
312			void replaysTheFirstRequestsResponse() {
313				willReturn(new TransferResponse(31L, 5L, 9L, TransferStatus.PENDING,
314						100_50L, Currency.EUR, 100_50L, Currency.EUR, REQUESTED_AT))
315						.given(requests).executeOnce(any(), any(), eq(TransferResponse.class), any(), any());
316	
317				MvcTestResult result = request(VALID_PAYLOAD);
318	
319				assertThat(result).hasStatus(HttpStatus.CREATED);
320				assertThat(result).hasHeader(HttpHeaders.LOCATION, "/api/transfers/31");
321				assertThat(result).bodyJson().extractingPath("$.id").isEqualTo(31);
322				then(reservation).shouldHaveNoInteractions();
323			}
324	
325			/**
326			 * Retryable, and the header is what says so. A client meeting this one has sent a
327			 * request that may still succeed under the very key it is holding, so the only
328			 * correct action is to wait and send it again.
329			 */
330			@Test
331			@DisplayName("whose first request has not finished is 409 with Retry-After")
332			void refusesAKeyWhoseWorkIsUnfinished() {
333				willThrow(new RequestInProgressException(IDEMPOTENCY_KEY))
334						.given(requests).executeOnce(any(), any(), any(), any(), any());
335	
336				MvcTestResult result = request(VALID_PAYLOAD);
337	
338				assertThatIsAConflict(result, ProblemType.REQUEST_IN_PROGRESS);
339				assertThat(result).headers().hasSingleValue(HttpHeaders.RETRY_AFTER, "1");
340				then(reservation).shouldHaveNoInteractions();
341			}
342	
343			/**
344			 * The refusal a client must never repeat, and the absent header is what says so.
345			 * Retrying cannot make two payloads agree, so a {@code Retry-After} here would
346			 * invite a loop that can only ever be refused again.
347			 */
348			@Test
349			@DisplayName("carrying a different payload is 409 with no Retry-After")
350			void refusesAKeyReusedForADifferentPayload() {
351				willThrow(new IdempotencyKeyReusedException(IDEMPOTENCY_KEY))
352						.given(requests).executeOnce(any(), any(), any(), any(), any());
353	
354				MvcTestResult result = request(VALID_PAYLOAD);
355	
356				assertThatIsAConflict(result, ProblemType.IDEMPOTENCY_KEY_REUSED);
357				assertThat(result).doesNotContainHeader(HttpHeaders.RETRY_AFTER);
358				then(reservation).shouldHaveNoInteractions();
359			}
360	
361			/**
362			 * What the port is given to decide with. The hash is the parsed request's own, so a
363			 * second posting of the same Transfer produces the same value however its JSON was
364			 * spelled — which is why this one is posted with its members reordered and padded.
365			 */
366			@Test
367			@DisplayName("is decided from the key and what the request said, not from the bytes that carried it")
368			void handsThePortTheKeyAndThePayloadsHash() {
369				request("""
370						{"amountMinorUnits": 10050,   "toAccountId": 9, "fromAccountId": 5}""");
371	
372				then(requests).should().executeOnce(eq(IDEMPOTENCY_KEY),
373						eq(new CreateTransferRequest(5L, 9L, 100_50L).payloadHash()),
374						eq(TransferResponse.class), any());
375			}
376		}
377	
378		/**
379		 * A Transfer of nothing is not a smaller Transfer, and one of a negative amount is a
380		 * Transfer in the other direction wearing the wrong Accounts. Both are refused against
381		 * the field that carried them rather than reaching the reservation, where the source
382		 * Account's Reserved Amount would move the wrong way.
383		 */
384		@ParameterizedTest(name = "an amount of {0} Minor Units is refused")
385		@ValueSource(longs = {0L, -1L})
386		void refusesANonPositiveAmount(long amountMinorUnits) {
387			MvcTestResult result = request("""
388					{"fromAccountId": 5, "toAccountId": 9, "amountMinorUnits": %d}""".formatted(amountMinorUnits));
389	
390			assertThatNamesARejectedField(result, "amountMinorUnits");
391			then(reservation).shouldHaveNoInteractions();
392		}
393	
394		@Test
395		@DisplayName("an empty request names all three missing fields, not just the first")
396		void namesEveryMissingField() {
397			MvcTestResult result = request("{}");
398	
399			assertThat(result).hasStatus(HttpStatus.BAD_REQUEST);
400			assertThat(result).bodyJson()
401					.extractingPath("$.errors[*].field").asInstanceOf(LIST)
402					.containsExactly("amountMinorUnits", "fromAccountId", "toAccountId");
403			then(reservation).shouldHaveNoInteractions();
404		}
405	
406		/**
407		 * The refusals that cannot be decided from the payload alone, each arriving from the
408		 * reservation as its own exception and leaving as its own {@code type} URN. The status
409		 * is {@code 422} throughout: every one of them is a well-formed request this API
410		 * understood and would not carry out, which is a different thing from the {@code 400}s
411		 * above.
412		 *
413		 * <p>Told apart by their URN and not by their status, because a client that had to read
414		 * {@code detail} to know which of the four it met would be parsing prose.
415		 */
416		@Nested
417		@DisplayName("a refusal from the reservation")
418		class Refusals {
419	
420			@Test
421			@DisplayName("names the Account a Transfer to itself was asked for")
422			void namesTheAccountOfASelfTransfer() {
423				given(reservation.reserve(any(), any())).willThrow(new SelfTransferNotAllowedException(5L));
424	
425				MvcTestResult result = request("""
426						{"fromAccountId": 5, "toAccountId": 5, "amountMinorUnits": 10050}""");
427	
428				assertThatIsARefusal(result, ProblemType.SELF_TRANSFER);
429				assertThat(result).bodyJson().extractingPath("$.accountId").isEqualTo(5);
430			}
431	
432			/**
433			 * A Transfer has two Accounts, so "one of them does not exist" is not an answer a
434			 * client can act on. The ID travels with the refusal for that reason alone.
435			 */
436			@Test
437			@DisplayName("says which of the two Accounts does not exist")
438			void saysWhichAccountDoesNotExist() {
439				given(reservation.reserve(any(), any())).willThrow(new UnknownAccountException(9L));
440	
441				MvcTestResult result = request(VALID_PAYLOAD);
442	
443				assertThatIsARefusal(result, ProblemType.UNKNOWN_ACCOUNT);
444				assertThat(result).bodyJson().extractingPath("$.accountId").isEqualTo(9);
445			}
446	
447			/**
448			 * Both figures that were compared, because neither survives the refusal: the
449			 * transaction that read the Available Balance has rolled back by the time the client
450			 * sees this, so a client that wanted to show the shortfall would otherwise have to
451			 * re-read an Account that may have moved again.
452			 */
453			@Test
454			@DisplayName("reports both amounts an overdraft check compared")
455			void reportsBothAmountsTheOverdraftCheckCompared() {
456				given(reservation.reserve(any(), any())).willThrow(new InsufficientFundsException(
457						new Money(40_00L, Currency.EUR), new Money(100_50L, Currency.EUR)));
458	
459				MvcTestResult result = request(VALID_PAYLOAD);
460	
461				assertThatIsARefusal(result, ProblemType.INSUFFICIENT_FUNDS);
462				assertThat(result).bodyJson().extractingPath("$.availableBalanceMinorUnits").isEqualTo(4000);
463				assertThat(result).bodyJson().extractingPath("$.requestedAmountMinorUnits").isEqualTo(10050);
464				assertThat(result).bodyJson().extractingPath("$.currency").isEqualTo("EUR");
465			}
466	
467			/**
468			 * Refused rather than converted, and refused rather than written: until ticket 26
469			 * fetches an Exchange Rate there is no figure to credit the destination Account
470			 * with, and the Currency this endpoint can derive is the source Account's alone.
471			 */
472			@Test
473			@DisplayName("names both Currencies of a Transfer this service cannot convert yet")
474			void namesBothCurrenciesOfATransferItCannotConvert() {
475				given(reservation.reserve(any(), any()))
476						.willThrow(new CrossCurrencyTransferNotSupportedException(Currency.EUR, Currency.HUF));
477	
478				MvcTestResult result = request(VALID_PAYLOAD);
479	
480				assertThatIsARefusal(result, ProblemType.CROSS_CURRENCY_UNSUPPORTED);
481				assertThat(result).bodyJson().extractingPath("$.sourceCurrency").isEqualTo("EUR");
482				assertThat(result).bodyJson().extractingPath("$.destinationCurrency").isEqualTo("HUF");
483			}
484		}
485	
486		private MvcTestResult request(String body) {
487			return requestWithKey(IDEMPOTENCY_KEY, body);
488		}
489	
490		private MvcTestResult requestWithKey(String idempotencyKey, String body) {
491			return requestWithNoKey(body).header("X-Idempotency-Key", idempotencyKey).exchange();
492		}
493	
494		private MockMvcTester.MockMvcRequestBuilder requestWithNoKey(String body) {
495			return mvc.post().uri("/api/transfers")
496					.contentType(MediaType.APPLICATION_JSON)
497					.content(body);
498		}
499	
500		/**
501		 * One shape and one discriminator, whichever refusal it is — the same claim
502		 * {@code ProblemDocumentContractTest} makes for the framework's own failures, made here
503		 * for the ones this slice raises deliberately.
504		 */
505		private static void assertThatIsARefusal(MvcTestResult result, ProblemType expected) {
506			assertThat(result).hasStatus(HttpStatus.UNPROCESSABLE_ENTITY);
507			assertThat(result).hasContentTypeCompatibleWith(MediaType.APPLICATION_PROBLEM_JSON);
508			assertThat(result).bodyJson().extractingPath("$.type").isEqualTo(expected.urn());
509			assertThat(result).bodyJson().extractingPath("$.title").isNotNull();
510			assertThat(result).bodyJson().extractingPath("$.detail").asString().isNotBlank();
511			assertThat(result).bodyJson().extractingPath("$.status").isEqualTo(422);
512			assertThat(result).bodyJson().extractingPath("$.instance").isEqualTo("/api/transfers");
513		}
514	
515		/**
516		 * The two refusals that share {@code 409} and disagree about everything else. The status
517		 * is asserted here and the header at each call site, because the header is the one part
518		 * they do not share.
519		 */
520		private static void assertThatIsAConflict(MvcTestResult result, ProblemType expected) {
521			assertThat(result).hasStatus(HttpStatus.CONFLICT);
522			assertThat(result).hasContentTypeCompatibleWith(MediaType.APPLICATION_PROBLEM_JSON);
523			assertThat(result).bodyJson().extractingPath("$.type").isEqualTo(expected.urn());
524			assertThat(result).bodyJson().extractingPath("$.title").isNotNull();
525			assertThat(result).bodyJson().extractingPath("$.detail").asString().isNotBlank();
526			assertThat(result).bodyJson().extractingPath("$.status").isEqualTo(409);
527			assertThat(result).bodyJson().extractingPath("$.instance").isEqualTo("/api/transfers");
528		}
529	
530		/**
531		 * A refusal a client can mark up against the input that caused it: the one problem
532		 * document of design decision 18, with an entry naming what was rejected. The shape
533		 * does not depend on whether the bad value arrived in the body or in a header, which is
534		 * a distinction no client can see well enough to branch on.
535		 */
536		private static void assertThatNamesARejectedField(MvcTestResult result, String field) {
537			assertThat(result).hasStatus(HttpStatus.BAD_REQUEST);
538			assertThat(result).hasContentTypeCompatibleWith(MediaType.APPLICATION_PROBLEM_JSON);
539			assertThat(result).bodyJson().extractingPath("$.type").isEqualTo(ProblemType.VALIDATION_FAILED.urn());
540			assertThat(result).bodyJson()
541					.extractingPath("$.errors[*].field").asInstanceOf(LIST)
542					.containsExactly(field);
543			assertThat(result).bodyJson()
544					.extractingPath("$.errors[0].message").asString().isNotBlank();
545		}
546	
547		/**
548		 * The identifier is the database's to hand out, so a Transfer that has one is one that
549		 * has been saved — the state this test has to stand in for.
550		 */
551		private static Transfer pendingTransfer(long id, ReservationRequest request, ConvertedAmounts amounts) {
552			Transfer transfer = new Transfer(request.sourceAccountId(), request.destinationAccountId(),
553					amounts, request.requestedAt());
554			ReflectionTestUtils.setField(transfer, "id", id);
555			return transfer;
556		}
557	
558		/**
559		 * Both phases stubbed for one request, because the endpoint reaches them in order and a
560		 * test that stubbed only the second would be asserting against the {@code null} the first
561		 * one's mock hands back.
562		 *
563		 * <p>The same {@link ConvertedAmounts} instance goes into the reservation's stubbing as
564		 * comes out of the quote's, which is the wiring claim: what phase two resolved is what
565		 * phase three is given.
566		 */
567		private Transfer stubBothPhases(long id, ReservationRequest request, ConvertedAmounts amounts) {
568			Transfer transfer = pendingTransfer(id, request, amounts);
569			given(quotes.convert(request)).willReturn(amounts);
570			given(reservation.reserve(request, amounts)).willReturn(transfer);
571			return transfer;
572		}
573	
574		/** A Transfer between two Accounts in one Currency, which is most of the cases here. */
575		private static ConvertedAmounts sameCurrency(ReservationRequest request, Currency currency) {
576			return ConvertedAmounts.unconverted(new Money(request.amountMinorUnits(), currency));
577		}
578	}
