1	package hu.bankmonitor.testsupport;
2	
3	import hu.bankmonitor.payments.common.Currency;
4	import hu.bankmonitor.payments.common.Money;
5	import hu.bankmonitor.payments.transfers.TransferStatus;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	
8	import java.time.Instant;
9	import java.time.ZoneOffset;
10	
11	/**
12	 * Transfer and Account rows written straight to the tables, for the tests that read
13	 * Transfers back.
14	 *
15	 * <p>Why SQL rather than the application's own path: a Transfer the application can produce
16	 * is {@code PENDING} and nothing else, because design decision 11 leaves each transition to
17	 * the ticket that has a caller for it. A test of a listing that reports four statuses cannot
18	 * be written against a path that reaches one, so the rows are placed rather than made. The
19	 * same reasoning is recorded in {@code AccountListingTest} for the Available Balance.
20	 *
21	 * <p>Static rather than an injected fixture so that a test's {@code @AfterEach} cannot depend
22	 * on a {@code @BeforeEach} having run first to build it — which is the very ordering trap
23	 * {@link #startFromTwoAccountsAndNoTransfers} exists to avoid.
24	 */
25	public final class TransferRows {
26	
27		/** The two Accounts every Transfer written here moves money between. */
28		public static final long SOURCE_ACCOUNT = 1L;
29	
30		public static final long DESTINATION_ACCOUNT = 2L;
31	
32		private TransferRows() {
33		}
34	
35		/**
36		 * Emptied and reopened in one method rather than two: JUnit promises no order between two
37		 * {@code @BeforeEach} methods, and opening the Accounts before the delete would leave
38		 * every insert that follows without the rows its foreign keys point at.
39		 */
40		public static void startFromTwoAccountsAndNoTransfers(JdbcTemplate jdbc) {
41			empty(jdbc);
42			openAccount(jdbc, SOURCE_ACCOUNT, Currency.EUR);
43			openAccount(jdbc, DESTINATION_ACCOUNT, Currency.EUR);
44		}
45	
46		/** Transfers first, then Accounts: each Transfer row points at the two below it. */
47		public static void empty(JdbcTemplate jdbc) {
48			jdbc.update("DELETE FROM transfers");
49			jdbc.update("DELETE FROM accounts");
50		}
51	
52		public static void openAccount(JdbcTemplate jdbc, long id, Currency currency) {
53			jdbc.update("""
54					INSERT INTO accounts (id, balance_minor_units, balance_currency,
55					                      reserved_amount_minor_units, reserved_amount_currency)
56					VALUES (?, 1000000, ?, 0, ?)
57					""", id, currency.name(), currency.name());
58		}
59	
