1	package hu.bankmonitor.payments.idempotency;
2	
3	import hu.bankmonitor.testsupport.BootedApplicationTest;
4	import org.junit.jupiter.api.AfterEach;
5	import org.junit.jupiter.api.BeforeEach;
6	import org.junit.jupiter.api.DisplayName;
7	import org.junit.jupiter.api.Test;
8	import org.junit.jupiter.params.ParameterizedTest;
9	import org.junit.jupiter.params.provider.ValueSource;
10	import org.jspecify.annotations.Nullable;
11	import org.springframework.beans.factory.annotation.Autowired;
12	import org.springframework.dao.EmptyResultDataAccessException;
13	import org.springframework.jdbc.core.JdbcTemplate;
14	import org.springframework.transaction.support.TransactionSynchronizationManager;
15	
16	import javax.sql.DataSource;
17	import java.sql.Connection;
18	import java.sql.PreparedStatement;
19	import java.sql.SQLException;
20	import java.util.concurrent.atomic.AtomicBoolean;
21	import java.util.concurrent.atomic.AtomicInteger;
22	import java.util.concurrent.atomic.AtomicReference;
23	import java.util.function.Supplier;
24	
25	import static org.assertj.core.api.Assertions.assertThat;
26	import static org.assertj.core.api.Assertions.assertThatThrownBy;
27	
28	/**
29	 * The four answers a repeat of an Idempotency Key can get, and the one thing all four have
30	 * in common: the operation behind the key does not run a second time.
31	 *
32	 * <p>Every case is arranged by writing the claim it starts from straight into the table,
33	 * rather than by driving {@link IdempotencyClaims} to produce it. The states this method
34	 * branches on are the states a *previous* request left behind, and placing them says which
35	 * one is under test in the one line that sets it up — where reaching them through the claim
36	 * mechanics would make each case depend on the mechanics of the case before it.
37	 *
38	 * <p>Not transactional, for {@code TheTableDecidesWhoHoldsAKeyTest}'s reason one layer up:
39	 * the claim commits alone and the operation commits with the flip that closes it, and a
40	 * test that never commits cannot tell either apart from a test that does. Rows therefore
41	 * outlive the method that wrote them, so the table is emptied by hand.
42	 */
43	class WhatARepeatOfAKeyGetsBackTest extends BootedApplicationTest {
44	
45		private static final String KEY = "0d1f6c1e-6b0a-4a5f-9f1a-2c3d4e5f6a7b";
46	
47		private static final String PAYLOAD_HASH = "1".repeat(64);
48	
49		private static final String A_DIFFERENT_PAYLOAD_HASH = "2".repeat(64);
50	
51		private static final Answer ANSWER = new Answer(31L, "PENDING");
52	
53		private static final String STORED_ANSWER = "{\"id\":31,\"status\":\"PENDING\"}";
54	
55		private static final Answer A_DIFFERENT_ANSWER = new Answer(32L, "PENDING");
56	
57		/** Stands in for the response an endpoint hands back and a repeat of the key replays. */
58		record Answer(long id, String status) {
59		}
60	
61		@Autowired
62		private IdempotentExecution requests;
63	
64		@Autowired
65		private JdbcTemplate jdbc;
66	
67		@Autowired
68		private DataSource dataSource;
69	
70		private final AtomicInteger runs = new AtomicInteger();
71	
72		/** Phase two, counted separately: a duplicate must not pay for it either. */
73		private final AtomicInteger resolutions = new AtomicInteger();
74	
75		@BeforeEach
76		@AfterEach
77		void dropEveryClaim() {
78			jdbc.update("DELETE FROM idempotency_records");
79		}
80	
81		@Test
82		@DisplayName("a key nobody has claimed runs the operation and stores what it answered")
83		void aFirstRequestRunsTheOperationAndStoresWhatItAnswered() {
84			assertThat(executeOnce(answering(ANSWER))).isEqualTo(ANSWER);
85	
86			assertThat(runs).hasValue(1);
87			assertThat(storedStatus()).isEqualTo("SUCCEEDED");
88			assertThat(storedResponseBody()).isEqualTo(STORED_ANSWER);
89		}
90	
91		/**
92		 * The guarantee itself: the second caller is handed the first caller's answer, and the
93		 * operation — which is where the money would move — is never reached. Both halves are
94		 * asserted, because an implementation that ran the operation again and happened to
95		 * return an equal answer would pass on the first half alone.
96		 */
97		@Test
98		@DisplayName("a repeat of a succeeded key replays the stored answer without running anything")
99		void aRepeatOfASucceededKeyReplaysTheStoredAnswer() {
100			claimedKey("SUCCEEDED", PAYLOAD_HASH, STORED_ANSWER);
101	
102			assertThat(executeOnce(answering(A_DIFFERENT_ANSWER))).isEqualTo(ANSWER);
103	
104			assertThat(runs).hasValue(0);
105		}
106	
107		@Test
108		@DisplayName("a repeat of a key whose work is unfinished is refused as in progress")
109		void aRepeatOfAnInProgressKeyIsRefusedAsInProgress() {
110			claimedKey("IN_PROGRESS", PAYLOAD_HASH, null);
111	
112			assertThatThrownBy(() -> executeOnce(answering(ANSWER)))
113					.isInstanceOf(RequestInProgressException.class);
114	
115			assertThat(runs).hasValue(0);
116			assertThat(storedStatus()).isEqualTo("IN_PROGRESS");
117		}
118	
119		/**
120		 * The mismatch is read before the status, which is what makes this a single row in the
121		 * table of outcomes rather than three. Whatever the first request got to, a second
122		 * payload under its key is a client mistake — and answering the {@code SUCCEEDED} case
123		 * with a replay would hand a client the response to a request it did not make.
124		 */
125		@ParameterizedTest(name = "over a claim that is {0}")
126		@ValueSource(strings = {"IN_PROGRESS", "SUCCEEDED", "FAILED"})
127		@DisplayName("a key carrying a different payload is refused as reused")
128		void aKeyReusedForADifferentPayloadIsRefusedWhateverItsClaimHasReached(String status) {
129			claimedKey(status, PAYLOAD_HASH, "SUCCEEDED".equals(status) ? STORED_ANSWER : null);
130	
131			assertThatThrownBy(() -> requests.executeOnce(KEY, A_DIFFERENT_PAYLOAD_HASH,
132					Answer.class, nothingToResolve(), resolved -> answering(ANSWER).get()))
133					.isInstanceOf(IdempotencyKeyReusedException.class);
134	
135			assertThat(runs).hasValue(0);
136			assertThat(resolutions).hasValue(0);
137			assertThat(storedStatus()).isEqualTo(status);
138		}
139	
140		/**
141		 * The row that makes the whole design work. A failed attempt leaves a key its own client
142		 * can take back, so every reservation-time failure is recoverable by sending the same
143		 * request again — which is what lets the client's retry policy be one line.
144		 */
145		@Test
146		@DisplayName("a retry of a failed key takes the claim back and executes")
147		void aRetryOfAFailedKeyExecutes() {
148			claimedKey("FAILED", PAYLOAD_HASH, null);
149	
150			assertThat(executeOnce(answering(ANSWER))).isEqualTo(ANSWER);
151	
152			assertThat(runs).hasValue(1);
153			assertThat(storedStatus()).isEqualTo("SUCCEEDED");
154			assertThat(storedResponseBody()).isEqualTo(STORED_ANSWER);
155		}
156	
157		/**
158		 * A failure is reported to its caller <em>and</em> released, which are two different
159		 * postconditions and only one of them is visible in the exception. Without the second,
160		 * a single refused request would burn its key permanently — the client is told to wait
161		 * for work that has already stopped.
162		 */
163		@Test
164		@DisplayName("an operation that throws releases the key, and the failure reaches the caller")
165		void anOperationThatThrowsReleasesTheKeyForARetry() {
166			assertThatThrownBy(() -> executeOnce(failing()))
167					.isInstanceOf(IllegalStateException.class)
168					.hasMessage("the reservation could not be made");
169	
170			assertThat(storedStatus()).isEqualTo("FAILED");
171			assertThat(storedResponseBody()).isNull();
172	
173			assertThat(executeOnce(answering(ANSWER))).isEqualTo(ANSWER);
174			assertThat(storedStatus()).isEqualTo("SUCCEEDED");
175		}
176	
177		/**
178		 * Design decision 4's phase two, and the placement that is its entire point: it runs
179		 * with the key already claimed and with no transaction open, where the operation runs
180		 * inside one.
181		 *
182		 * <p>Both halves matter and only together. That the resolution ran <em>after</em> the
183		 * claim is what stops a duplicate paying for it; that it ran <em>outside</em> the
184		 * transaction is what keeps a slow Exchange Rate provider from being something the
185		 * Account row locks wait on. Moving the call one line down, inside the transaction
186		 * template, would leave every other test in this class green.
187		 */
188		@Test
189		@DisplayName("phase two runs under the claim and outside the transaction the operation runs in")
190		void resolvesWithTheKeyClaimedAndNoTransactionOpen() {
191			AtomicBoolean transactionWhileResolving = new AtomicBoolean(true);
192			AtomicBoolean transactionWhileOperating = new AtomicBoolean(false);
193			AtomicReference<String> claimWhileResolving = new AtomicReference<>();
194	
195			Answer answered = requests.executeOnce(KEY, PAYLOAD_HASH, Answer.class,
196					() -> {
197						transactionWhileResolving.set(TransactionSynchronizationManager.isActualTransactionActive());
198						claimWhileResolving.set(storedStatus());
199						return "the resolved value";
200					},
201					resolved -> {
202						transactionWhileOperating.set(TransactionSynchronizationManager.isActualTransactionActive());
203						assertThat(resolved).as("what phase two produced reaches phase three")
204								.isEqualTo("the resolved value");
205						return ANSWER;
206					});
207	
208			assertThat(answered).isEqualTo(ANSWER);
209			assertThat(transactionWhileResolving).as("nothing slow may run inside the transaction").isFalse();
210			assertThat(transactionWhileOperating).as("the operation and the claim commit together").isTrue();
211			assertThat(claimWhileResolving).as("the claim is committed before phase two runs")
212					.hasValue("IN_PROGRESS");
213		}
214	
215		/**
216		 * The failure ticket 26 exists to handle: the Exchange Rate provider gave up, so nothing
217		 * was priced and nothing may be reserved. Failing to the caller is not giving up on the
218		 * key — the claim is released, so the same key resubmitted executes rather than replaying
219		 * a failure.
220		 */
221		@Test
222		@DisplayName("a phase two that throws releases the key without ever reaching the operation")
223		void aResolutionThatThrowsReleasesTheKeyAndRunsNothing() {
224			assertThatThrownBy(() -> executeOnce(
225					() -> {
226						resolutions.incrementAndGet();
227						throw new IllegalStateException("the provider did not answer");
228					},
229					answering(ANSWER)))
230					.isInstanceOf(IllegalStateException.class)
231					.hasMessage("the provider did not answer");
232	
233			assertThat(resolutions).hasValue(1);
234			assertThat(runs).as("nothing may be reserved at a rate nobody quoted").hasValue(0);
235			assertThat(storedStatus()).isEqualTo("FAILED");
236	
237			assertThat(executeOnce(answering(ANSWER))).isEqualTo(ANSWER);
238			assertThat(storedStatus()).isEqualTo("SUCCEEDED");
239		}
240	
241		/**
242		 * The claim is committed before the operation runs, which is the property the whole
243		 * mechanism rests on and the one a sequential test normally cannot see. Here the repeat
244		 * arrives from inside the operation itself, so it is demonstrably reading a claim whose
245		 * request has not finished.
246		 *
247		 * <p>What it leaves behind is the second half: the refusal travelled out through the
248		 * operation, so the outer request failed too, and its key is free for the retry that
249		 * both callers now owe.
250		 */
251		@Test
252		@DisplayName("a repeat arriving while the operation is still running sees the claim")
253		void aRepeatArrivingDuringTheOperationSeesTheClaim() {
254			assertThatThrownBy(() -> executeOnce(() -> {
255				runs.incrementAndGet();
256				return requests.executeOnce(KEY, PAYLOAD_HASH, Answer.class,
257						nothingToResolve(), resolved -> answering(ANSWER).get());
258			})).isInstanceOf(RequestInProgressException.class);
259	
260			assertThat(runs).hasValue(1);
261			assertThat(storedStatus()).isEqualTo("FAILED");
262		}
263	
264		/**
265		 * Releasing the claim can fail on its own, and it always fails while another exception
266		 * is already on its way up. The one the caller asked about wins; the bookkeeping failure
267		 * travels attached to it, because dropping it would leave a key stranded with nothing
268		 * anywhere saying so.
269		 *
270		 * <p>The claim is deleted on a second connection so that the deletion is real by the
271		 * time the operation throws — the operation's own transaction is about to roll back, and
272		 * anything it wrote would roll back with it.
273		 */
274		@Test
275		@DisplayName("a failure that cannot be recorded travels attached to the failure it reports")
276		void aFailureThatCannotBeRecordedIsAttachedToTheOriginal() {
277			assertThatThrownBy(() -> executeOnce(() -> {
278				deleteTheClaimOnAnotherConnection();
279				throw new IllegalStateException("the reservation could not be made");
280			}))
281					.isInstanceOf(IllegalStateException.class)
282					.hasMessage("the reservation could not be made")
283					.satisfies(failure -> assertThat(failure.getSuppressed())
284							.singleElement()
285							.isInstanceOf(EmptyResultDataAccessException.class));
286		}
287	
288		private @Nullable Answer executeOnce(Supplier<Answer> operation) {
289			return executeOnce(nothingToResolve(), operation);
290		}
291	
292		private @Nullable Answer executeOnce(Supplier<String> resolution, Supplier<Answer> operation) {
