1	package hu.bankmonitor.payments.transfers;
2	
3	import hu.bankmonitor.payments.common.Currency;
4	import hu.bankmonitor.payments.common.ProblemType;
5	import org.junit.jupiter.api.BeforeEach;
6	import org.junit.jupiter.api.DisplayName;
7	import org.junit.jupiter.api.Test;
8	import org.springframework.http.HttpHeaders;
9	import org.springframework.http.MediaType;
10	import org.springframework.test.web.servlet.client.RestTestClient;
11	
12	import static org.assertj.core.api.Assertions.assertThat;
13	
14	/**
15	 * The requirement itself, over a real socket: the same Transfer requested twice under one
16	 * Idempotency Key moves money once.
17	 *
18	 * <p>{@code WhatARepeatOfAKeyGetsBackTest} makes the same four claims against the port with
19	 * a stand-in operation, and {@link TransferRequestContractTest} makes them against the wire
20	 * with the port stubbed. Each is green while the two halves are wired to nothing, and each
21	 * has to place the claim it starts from by hand. Here nothing is placed: every state a
22	 * repeat meets was left behind by an earlier request through the same endpoint, which is
23	 * the only arrangement that can be wrong in the way production would be.
24	 *
25	 * <p>It is also the only place the bundling of design decision 4 is visible. Phase three
26	 * commits the reservation, the Transfer and the flip to {@code SUCCEEDED} together, so the
27	 * assertion that says so is not about any one of them: it is that all three are there after
28	 * a request that worked, and that none of them is after a request that was refused.
29	 */
30	class RetryingATransferRequestMovesMoneyOnceTest extends TransferScenario {
31	
32		private static final long SOURCE = 1L;
33	
34		private static final long DESTINATION = 2L;
35	
36		private static final long BALANCE = 1_000_00L;
37	
38		private static final long AMOUNT = 100_50L;
39	
40		private static final String KEY = "0d1f6c1e-6b0a-4a5f-9f1a-2c3d4e5f6a7b";
41	
42		private static final String A_SECOND_KEY = "7c9e6679-7425-40de-944b-e07fc1f90ae7";
43	
44		private static final String TRANSFER = """
45				{"fromAccountId": 1, "toAccountId": 2, "amountMinorUnits": 10050}""";
46	
47		private static final String A_DIFFERENT_TRANSFER = """
48				{"fromAccountId": 1, "toAccountId": 2, "amountMinorUnits": 20000}""";
49	
50		@BeforeEach
51		void openTheTwoAccounts() {
52			openAccount(SOURCE, BALANCE, Currency.EUR);
53			openAccount(DESTINATION, BALANCE, Currency.EUR);
54		}
55	
56		/**
57		 * The guarantee. The second request is answered from what the first one stored, so the
58		 * two responses agree member for member and point at the same Transfer — and the tables
59		 * say that Transfer is the only one, with the amount reserved once rather than twice.
60		 *
61		 * <p>Both halves are needed. A service that reserved the funds again and returned the
62		 * second Transfer would satisfy neither, but one that reserved again and happened to
63		 * answer with the first Transfer's shape would satisfy the response assertion alone.
64		 */
65		@Test
66		@DisplayName("the same Transfer sent twice under one key creates one Transfer and reserves once")
67		void aRepeatIsAnsweredFromTheFirstRequestAndReservesNothingMore() {
68			TransferResponse first = requestTransfer(KEY, TRANSFER).expectStatus().isCreated()
69					.expectBody(TransferResponse.class).returnResult().getResponseBody();
70	
71			TransferResponse repeat = requestTransfer(KEY, TRANSFER).expectStatus().isCreated()
72					.expectHeader().valueEquals(HttpHeaders.LOCATION, "/api/transfers/" + first.id())
73					.expectBody(TransferResponse.class).returnResult().getResponseBody();
74	
75			assertThat(repeat).isEqualTo(first);
76			assertThat(transferRows()).singleElement()
77					.extracting(row -> row.get("ID")).isEqualTo(first.id());
78			assertThat(reservedAmountOf(SOURCE)).isEqualTo(AMOUNT);
79			assertThat(availableBalanceOf(SOURCE)).isEqualTo(BALANCE - AMOUNT);
80			assertThat(claimedStatus(KEY)).isEqualTo("SUCCEEDED");
81		}
82	
83		/**
84		 * Design decision 4's bundling, seen from the side where nothing happened: a refused
85		 * request leaves no reservation, no Transfer and no Check Ledger, and its key is
86		 * {@code FAILED} rather than stuck at {@code IN_PROGRESS}. Any of those four disagreeing
87		 * with the others is the crash window the bundle exists to close.
88		 */
89		@Test
90		@DisplayName("a refused request reserves nothing, writes nothing, and leaves its key retryable")
91		void aRefusedRequestWritesNothingAndReleasesItsKey() {
92			requestTransfer(KEY, tooLargeATransfer()).expectStatus().isEqualTo(422)
93					.expectBody().jsonPath("$.type").isEqualTo(ProblemType.INSUFFICIENT_FUNDS.urn());
94	
95			assertThat(reservedAmountOf(SOURCE)).isZero();
96			assertThat(transferRows()).isEmpty();
97			assertThat(checkLedgerRows()).isEmpty();
98			assertThat(claimedStatus(KEY)).isEqualTo("FAILED");
99		}
100	
101		/**
102		 * What a released key is for. The operator funds the Account and sends the very same
103		 * request again — same key, same payload — and it goes through, which is what lets a
104		 * client's retry policy be "resend it" rather than "work out whether the first one took
105		 * effect".
106		 */
107		@Test
108		@DisplayName("resending a request that was refused, once its reason is gone, creates the Transfer")
109		void aRetryOfARefusedRequestExecutes() {
110			requestTransfer(KEY, tooLargeATransfer()).expectStatus().isEqualTo(422);
111	
112			payInTwiceTheBalance();
113	
114			TransferResponse retried = requestTransfer(KEY, tooLargeATransfer())
115					.expectStatus().isCreated()
116					.expectBody(TransferResponse.class).returnResult().getResponseBody();
117	
118			assertThat(retried.status()).isEqualTo(TransferStatus.PENDING);
119			assertThat(transferRows()).singleElement()
120					.extracting(row -> row.get("ID")).isEqualTo(retried.id());
121			assertThat(claimedStatus(KEY)).isEqualTo("SUCCEEDED");
122		}
123	
124		/**
125		 * The other {@code 409}, end to end: a key that already stands for one Transfer will not
126		 * carry another, whatever the first one got to. No {@code Retry-After}, because no amount
127		 * of retrying will make the two payloads agree — and no second Transfer, which is the
128		 * refusal doing its job rather than merely announcing itself.
129		 */
130		@Test
131		@DisplayName("a second Transfer sent under a spent key is refused, and none is created")
132		void aKeyReusedForADifferentTransferIsRefused() {
133			requestTransfer(KEY, TRANSFER).expectStatus().isCreated();
134	
135			requestTransfer(KEY, A_DIFFERENT_TRANSFER).expectStatus().isEqualTo(409)
136					.expectHeader().doesNotExist(HttpHeaders.RETRY_AFTER)
137					.expectBody().jsonPath("$.type").isEqualTo(ProblemType.IDEMPOTENCY_KEY_REUSED.urn());
138	
139			assertThat(transferRows()).hasSize(1);
140			assertThat(reservedAmountOf(SOURCE)).isEqualTo(AMOUNT);
141		}
142	
143		/**
144		 * The key is what identifies a repeat, and nothing else is: the same payload under a new
145		 * key is a second Transfer the operator meant to make, not a retry to be swallowed.
146		 */
147		@Test
148		@DisplayName("the same Transfer under a new key is a second Transfer")
149		void theSameTransferUnderANewKeyIsASecondTransfer() {
150			requestTransfer(KEY, TRANSFER).expectStatus().isCreated();
151			requestTransfer(A_SECOND_KEY, TRANSFER).expectStatus().isCreated();
152	
153			assertThat(transferRows()).hasSize(2);
154			assertThat(reservedAmountOf(SOURCE)).isEqualTo(2 * AMOUNT);
155		}
156	
157		private RestTestClient.ResponseSpec requestTransfer(String idempotencyKey, String body) {
158			return client().post().uri("/api/transfers")
159					.header("X-Idempotency-Key", idempotencyKey)
160					.contentType(MediaType.APPLICATION_JSON)
161					.body(body)
162					.exchange();
163		}
164	
165		/** More than the source Account holds, so the overdraft check refuses it under the lock. */
166		private static String tooLargeATransfer() {
167			return """
168					{"fromAccountId": 1, "toAccountId": 2, "amountMinorUnits": %d}"""
169					.formatted(BALANCE * 2);
170		}
171	
172		private void payInTwiceTheBalance() {
173			database.update("UPDATE accounts SET balance_minor_units = ? WHERE id = ?",
174					BALANCE * 3, SOURCE);
175		}
176	}
