import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Import;
import org.springframework.http.MediaType;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * The placement the whole locking design rests on, asserted from where it can actually be
 * wrong: the Exchange Rate provider itself, during a real request over a real socket.
 *
 * <p>Design decision 6 answers the classic objection to pessimistic locking — that a lock
 * held across a call to a third party makes every other request touching those rows wait on
 * somebody else's server — by putting the fetch in a phase of its own, above the transaction.
 * Nothing about that is visible in what a request returns. A version that fetched the rate
 * one line lower, inside the transaction, would convert correctly, credit correctly and
 * answer identically, and would be exactly the design this application claims not to have.
 *
 * <p><b>No lock held follows from no transaction open, and is not asserted separately.</b> A
 * pessimistic lock is taken by a query inside a transaction and released when that
 * transaction ends, so it cannot outlive one; a provider called with no transaction active
 * is a provider no row lock is waiting on. There is nothing further to observe from here —
 * the locks belong to a transaction that has not started.
 *
 * <p>{@code WhatARepeatOfAKeyGetsBackTest} makes the same claim one layer down, about the
 * port, with a stand-in resolution. That one holds the port to its contract; this one holds
 * the endpoint to using it as intended, which is a different mistake and the likelier of the
 * two.
 */
@Import(ScriptedExchangeRates.class)
class TheRateIsFetchedWithNoTransactionOpenTest extends TransferScenario {

	private static final long SOURCE = 1L;

	private static final long DESTINATION = 2L;

	private static final String KEY = "0d1f6c1e-6b0a-4a5f-9f1a-2c3d4e5f6a7b";

	@Autowired
	private ScriptedExchangeRates rates;

	@BeforeEach
	void openTwoAccountsInDifferentCurrencies() {
		rates.forgetEverything();
		rates.quoteAt("390");
		openAccount(SOURCE, 1_000_00L, Currency.EUR);
		openAccount(DESTINATION, 0L, Currency.HUF);
	}

	@Test
	@DisplayName("the provider is called with no transaction open, so no Account row lock waits on it")
	void asksTheProviderBeforeAnyTransactionIsOpen() {
		client().post().uri("/api/transfers")
				.header("X-Idempotency-Key", KEY)
				.contentType(MediaType.APPLICATION_JSON)
				.body("""
						{"fromAccountId": 1, "toAccountId": 2, "amountMinorUnits": 10050}""")
				.exchange()
				.expectStatus().isCreated();

		assertThat(rates.pairsAsked())
				.as("the request has to have reached the provider for the rest to mean anything")
				.containsExactly("EUR/HUF");
		assertThat(rates.sawAnOpenTransaction())
				.as("a transaction here would be one holding both Account row locks")
				.isFalse();
	}
}

